using QRCoder; using PresenterConsole.Sync; namespace PresenterConsole.Desktop; public sealed class MainForm:Form { readonly Label status=new(){Text="未連線",AutoSize=true}; readonly Label slide=new(){Text="目前頁碼：—",AutoSize=true}; readonly PictureBox qr=new(){Size=new Size(260,260),SizeMode=PictureBoxSizeMode.Zoom}; readonly IPresentationAdapter ppt=new PowerPointAdapter(); readonly SyncEngine sync=new(); AgentServer? server; public MainForm(){Text="Presenter Console Agent";Width=500;Height=500;var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown};p.Controls.Add(status);p.Controls.Add(slide);p.Controls.Add(qr);Controls.Add(p);ppt.StateChanged+=(_,_)=>BeginInvoke(RefreshState);Load+=async(_,_)=>{server=new AgentServer(ppt,sync);await server.StartAsync(CancellationToken.None);RefreshState();};FormClosed+=(_,_)=>{server?.DisposeAsync();sync.Dispose();ppt.Dispose();};} void RefreshState(){slide.Text=$"目前頁碼：{ppt.CurrentShowPosition}/{ppt.SlideCount}";status.Text="Agent 已啟動 · LAN:5217";using var d=new QRCodeGenerator().CreateQrCode("http://"+Environment.MachineName+":5217",QRCodeGenerator.ECCLevel.Q);qr.Image=new PngByteQRCode(d).GetGraphic(8);}}